}

detect_tool "Git"      "git"
detect_tool "GitHub CLI" "gh"
detect_tool "jq"       "jq"
detect_tool "Bash"     "bash"
detect_tool "PowerShell" "pwsh"

detect_tool "Node.js"  "node"
detect_tool "pnpm"     "pnpm"
