fi

# ── Git information ──────────────────────────────────────────────────────
git_summary=""
if command -v git &>/dev/null && git -C "$CWD" rev-parse --is-inside-work-tree &>/dev/null; then
    git_branch=$(git -C "$CWD" branch --show-current 2>/dev/null || echo "detached")
    git_status=$(git -C "$CWD" status --short 2>/dev/null || true)
