  escaped_summary=$(printf '%s' "$env_summary" | awk '{gsub(/\\/, "\\\\"); gsub(/"/, "\\\""); printf "%s\\n", $0}' | sed '$ s/\\n$//')
  printf '{"hookSpecificOutput":{"additionalContext":"%s"}}\n' "$escaped_summary"
